package com.rosery.app;
import android.content.Intent;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.rosery.app.model.Product;import com.rosery.app.model.ProductRepository;
public class CheckoutActivity extends AppCompatActivity{
 protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_checkout);findViewById(R.id.checkoutBackButton).setOnClickListener(v->finish());((TextView)findViewById(R.id.checkoutTotal)).setText("৳ "+CartManager.total());EditText address=findViewById(R.id.addressInput),phone=findViewById(R.id.phoneInput);RadioGroup group=findViewById(R.id.paymentGroup);
 findViewById(R.id.placeOrderButton).setOnClickListener(v->{String a=address.getText().toString().trim(),ph=phone.getText().toString().trim();if(a.length()<8||ph.length()<8){Toast.makeText(this,"Enter a valid address and phone number.",Toast.LENGTH_SHORT).show();return;}for(Product p:CartManager.getItems()){if(CartManager.getQuantity(p)>ProductRepository.getStock(this,p.id)){Toast.makeText(this,p.name+" is out of stock. Available: "+ProductRepository.getStock(this,p.id),Toast.LENGTH_LONG).show();return;}}String payment=group.getCheckedRadioButtonId()==R.id.onlinePayment?"Online Payment (Demo)":"Cash on Delivery";String id=OrderManager.create(this,a,ph,payment,CartManager.total(),CartManager.count());for(Product p:CartManager.getItems())ProductRepository.reduceStock(this,p.id,CartManager.getQuantity(p));CartManager.clear();Toast.makeText(this,"Order "+id+" placed successfully!",Toast.LENGTH_LONG).show();Intent i=new Intent(this,OrdersActivity.class);i.putExtra("newOrderId",id);startActivity(i);finish();});
 }
}
